-- M6 §6.11: verification_level_changes only grows. It is the record of WHY a user is allowed to
-- transact — which provider attested what, when, and who overrode it — and a record that can be
-- rewritten is not a record. Same posture M1 §5.11 takes for identity_audit_log and M20 §3.6 for
-- file_access_log. Generated by appendOnly() in src/db/helpers/appendOnly.ts: UPDATE and DELETE
-- raise KT001 for everyone including the owner, and komtru_app holds INSERT and SELECT only.
-- grantRuntimeAccess() finds the trigger on every later migrate run and keeps the privileges narrow.
--
-- Note what this does to the foreign key from verification_requests: it is ON DELETE NO ACTION, so a
-- request with level history cannot be deleted at all. That is deliberate — a level grant whose
-- triggering request vanished is an audit trail with a hole in exactly the place an auditor looks.
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "trust"."verification_level_changes" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "trust"."verification_level_changes" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "trust"."verification_level_changes" TO komtru_app;
